package com.shipflow.order.application;
import com.shipflow.order.api.model.*; import com.shipflow.order.domain.model.ShipmentOrder; import com.shipflow.order.mapper.ShipmentOrderMapper; import com.shipflow.order.mapper.OrderActionIdempotencyMapper; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.dao.DuplicateKeyException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.HexFormat;
@Service public class ShipmentOrderLifecycleApplicationService { private final ShipmentOrderMapper mapper; private final ShipmentOrderQueryApplicationService query; private final Clock clock; private final OrderActionIdempotencyMapper idempotency; public ShipmentOrderLifecycleApplicationService(ShipmentOrderMapper mapper,ShipmentOrderQueryApplicationService query,Clock clock){this(mapper,query,clock,null);} @Autowired public ShipmentOrderLifecycleApplicationService(ShipmentOrderMapper mapper,ShipmentOrderQueryApplicationService query,Clock clock,OrderActionIdempotencyMapper idempotency){this.mapper=mapper;this.query=query;this.clock=clock;this.idempotency=idempotency;}
 @Transactional public ShipmentOrderResponse updateDraft(Long tenant,Long user,Long id,UpdateShipmentOrderRequest request,String requestId){ShipmentOrder order=query.require(mapper.findById(tenant,id));requireDraft(order); rejectPricingChanges(request); if(mapper.advanceDraftVersion(tenant,id,request.version())!=1)throw new ShipmentOrderException("COMMON-1005",409); if(mapper.updateAddresses(tenant,id,request.senderAddress(),request.receiverAddress())!=2)throw new IllegalStateException("Order address update failed"); mapper.deleteItems(tenant,id); int no=1;for(var item:request.items())mapper.insertDraftItem(tenant,id,no++,item); mapper.insertAuditAction(tenant,user,id,"UPDATE_DRAFT",requestId,"SUCCESS",null,LocalDateTime.now(clock));return query.response(query.require(mapper.findById(tenant,id)));}
 @Transactional public ShipmentOrderResponse submit(Long tenant,Long user,Long id,OrderActionRequest request,String requestId){return submit(tenant,user,id,request,null,requestId);} @Transactional public ShipmentOrderResponse submit(Long tenant,Long user,Long id,OrderActionRequest request,String key,String requestId){ShipmentOrderResponse replay=replay(tenant,id,"submitOrder",key,request,"/api/v1/orders/{orderId}/submit");if(replay!=null)return replay;ShipmentOrderResponse result=transition(tenant,user,id,request,"DRAFT","PENDING_INBOUND","SUBMIT",requestId);complete(tenant,"submitOrder",key,id);return result;}
 @Transactional public ShipmentOrderResponse cancel(Long tenant,Long user,Long id,OrderActionRequest request,String requestId){return cancel(tenant,user,id,request,null,requestId);} @Transactional public ShipmentOrderResponse cancel(Long tenant,Long user,Long id,OrderActionRequest request,String key,String requestId){ShipmentOrderResponse replay=replay(tenant,id,"cancelOrder",key,request,"/api/v1/orders/{orderId}/cancel");if(replay!=null)return replay;ShipmentOrder order=query.require(mapper.findById(tenant,id));if(!("DRAFT".equals(order.currentStatus())||"PENDING_INBOUND".equals(order.currentStatus())))throw new ShipmentOrderException("ORDER-1001",409); if(mapper.transitionStatus(tenant,id,order.currentStatus(),"CANCELLED",request.version())!=1)throw new ShipmentOrderException("COMMON-1005",409); mapper.insertAuditAction(tenant,user,id,"CANCEL",requestId,"SUCCESS",request.reason(),LocalDateTime.now(clock));ShipmentOrderResponse result=query.response(query.require(mapper.findById(tenant,id)));complete(tenant,"cancelOrder",key,id);return result;}
 private ShipmentOrderResponse transition(Long t,Long u,Long id,OrderActionRequest r,String from,String to,String action,String requestId){ShipmentOrder o=query.require(mapper.findById(t,id));if(!from.equals(o.currentStatus()))throw new ShipmentOrderException("ORDER-1001",409);if(mapper.transitionStatus(t,id,from,to,r.version())!=1)throw new ShipmentOrderException("COMMON-1005",409);mapper.insertAuditAction(t,u,id,action,requestId,"SUCCESS",r.reason(),LocalDateTime.now(clock));return query.response(query.require(mapper.findById(t,id)));}
 private ShipmentOrderResponse replay(Long tenant,Long id,String operation,String key,OrderActionRequest request,String path){if(key==null||key.isBlank()||idempotency==null)return null;if(key.length()>128)throw new ShipmentOrderException("COMMON-1001",400);String hash=hash(id+"\n"+request);var record=idempotency.find(tenant,operation,key);if(record==null)try{idempotency.insert(tenant,operation,key,hash,path,LocalDateTime.now(clock).plusMinutes(30));}catch(DuplicateKeyException ex){record=idempotency.find(tenant,operation,key);if(record==null)throw ex;}if(record==null)return null;if(!hash.equals(record.requestHash()))throw new ShipmentOrderException("COMMON-1009",409);if(record.resourceId()==null)throw new ShipmentOrderException("COMMON-1010",409);return query.response(query.require(mapper.findById(tenant,record.resourceId())));}
 private void complete(Long tenant,String operation,String key,Long id){if(key!=null&&!key.isBlank()&&idempotency!=null)idempotency.complete(tenant,operation,key,id);} private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private void requireDraft(ShipmentOrder o){if(!"DRAFT".equals(o.currentStatus()))throw new ShipmentOrderException("ORDER-1001",409);} private void rejectPricingChanges(UpdateShipmentOrderRequest r){if(r.channelId()!=null||r.destinationCountry()!=null||r.declaredWeight()!=null||r.declaredLength()!=null||r.declaredWidth()!=null||r.declaredHeight()!=null||r.packageCount()!=null||r.priceRuleVersion()!=null||r.chargeableWeight()!=null||r.amount()!=null||r.currency()!=null||r.quoteSnapshot()!=null)throw new ShipmentOrderException("ORDER-1007",422);}}
